; c02_mov_const -- MOV between regions, the constant pool, EXEC_CSR WRITE_SP
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: MainMoveDesc (regions, offsets, length) and its byte order; where the constant pool lies; byte order of a multi-byte write
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c02_mov_const.expected.csv
.include "conf_defs.inc"
.main
.const K_WORD dw 0x1234                        ; stored low byte first: 34 12
.const K_BYTES db 0x11, 0x22, 0x33, 0x44
    MOV MAIN_CONST_POOL[@K_WORD]  -> MAIN_SCRATCHPAD[0..1]
    EXEC_CSR WRITE_SP RES + 0, len=2, ptr=0
    MOV MAIN_CONST_POOL[@K_BYTES] -> MAIN_SCRATCHPAD[4..7]
    EXEC_CSR WRITE_SP RES + 4, len=4, ptr=4
    MOV MAIN_SCRATCHPAD[5..6] -> MAIN_SCRATCHPAD[10..11]     ; inside one region, not overlapping: source and destination offsets differ
    EXEC_CSR WRITE_SP RES + 8, len=2, ptr=10
    MOV CONST(0xCAFE, 2) -> MAIN_SCRATCHPAD[16..17]
    MOV MAIN_SCRATCHPAD[16..17] -> ALU_OPA                    ; through the ALU operand and back: OR with 0 changes nothing
    MOV CONST(0, 2) -> MAIN_SCRATCHPAD[18..19]
    MOV MAIN_SCRATCHPAD[18..19] -> ALU_OPB
    ALU OR
    MOV ALU_OUT[0..1] -> MAIN_SCRATCHPAD[20..21]
    EXEC_CSR WRITE_SP RES + 12, len=2, ptr=20
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
